#!/usr/bin/env bash
# pipeline.config.defaults.sh — SHIPPED DEFAULTS. Do not edit this file.
#
# It is sourced first by every script; your project's own
# $ROOT/.claude/pipeline.config.sh is then sourced ON TOP and overrides anything here
# (set $PIPELINE_CONFIG to point somewhere else). Editing this file instead means your
# settings are shared by every repo and are lost the next time you update the skill.
#
# When these are sourced, two variables are already set and may be referenced freely:
#   ROOT       — the main repo root (worktree-aware)
#   SKILL_DIR  — the installed skill bundle
#
# The pipeline runs on these defaults alone in a plain repo; `install.sh init` seeds a
# per-repo file for the things that genuinely differ per project.

# ── Runtime state ────────────────────────────────────────────────────────────
# Per-session state, epic logs, and manifests (relative to the main repo root).
# Deliberately not ".claude/codex" so the bundle never collides with another tool.
PIPELINE_RUNTIME_DIR=".claude/dev-pipeline"

# ── Git / worktree topology ──────────────────────────────────────────────────
# Base branch: PRs target it and worktrees fork from it. Default = the remote's default
# branch (origin/HEAD), falling back to main/master, so a fresh repo needs no config.
PIPELINE_BASE_BRANCH="$(
  git -C "$ROOT" symbolic-ref --quiet --short refs/remotes/origin/HEAD 2>/dev/null | sed 's|^origin/||' \
    || true
)"
if [ -z "$PIPELINE_BASE_BRANCH" ]; then
  if git -C "$ROOT" show-ref --verify --quiet refs/heads/main; then PIPELINE_BASE_BRANCH="main"
  elif git -C "$ROOT" show-ref --verify --quiet refs/heads/master; then PIPELINE_BASE_BRANCH="master"
  else PIPELINE_BASE_BRANCH="$(git -C "$ROOT" rev-parse --abbrev-ref HEAD 2>/dev/null || echo main)"
  fi
fi

# Where isolated worktrees are created. Left unset here; pipeline-lib defaults it to the
# sibling directory "<repo>-wt" and canonicalizes it.
PIPELINE_WORKTREE_ROOT="${PIPELINE_WORKTREE_ROOT:-}"

# Sub-directory the app lives in ("" = repo root). Monorepos set e.g. "packages/api".
PIPELINE_APP_SUBDIR=""

# ── Plans ────────────────────────────────────────────────────────────────────
# record-plan.sh stamps planPath into the writing session's state whenever a Write/Edit
# touches a path CONTAINING this fragment; spec-review lists candidate plans from it.
# "/plans/" deliberately matches both docs/plans/ and docs/superpowers/plans/.
PIPELINE_PLAN_GLOB="/plans/"

# ── Autonomous mode ──────────────────────────────────────────────────────────
# The epic orchestrator sets this env var to "auto" so both human gates go
# non-interactive. Pick any name that won't clash with your app's own env.
PIPELINE_AUTO_ENV="PIPELINE_MODE"

# ── Reviewer (headless) ──────────────────────────────────────────────────────
# Empty model = let the reviewer CLI use its own configured default (safest: model ids
# change often, and a stale pin fails the whole gate). Pin it per repo if you care.
REVIEWER_MODEL=""
REVIEWER_EFFORT="high"
# danger-full-access is REQUIRED for the default codex reviewer, not laziness:
#   * code review must reach the network to post via `gh` (workspace-write blocks network);
#   * plan review writes its verdict JSON to the MAIN repo's session dir while its cwd is the
#     worktree — outside the writable workspace.
# Narrow this only if you also move the verdict path inside the workdir and grant network.
REVIEWER_SANDBOX="danger-full-access"
REVIEWER_TIMEOUT="3600"    # seconds; 0 disables the cap

# Optional file appended verbatim to BOTH reviewer prompts as load-bearing repo rules.
REVIEW_RULES_FILE="$ROOT/.claude/REVIEW_RULES.md"

# reviewer_invoke <prompt-file> — run the headless reviewer with the prompt on stdin, in
# the current directory. Default: OpenAI `codex exec`. Override the whole function in your
# repo config to swap reviewers (another model, or Claude headless — anything that takes a
# prompt, reads the repo, and can call `gh`).
#
# NOTE: the reviewer must be able to WRITE its verdict file (plan review) and CALL gh
# (code review), so it needs at least workspace-write; the plan-review verdict path lives
# under the repo's own .claude/ runtime dir precisely so workspace-write suffices.
reviewer_invoke() {
  codex exec \
    ${REVIEWER_MODEL:+-m "$REVIEWER_MODEL"} \
    ${REVIEWER_EFFORT:+-c model_reasoning_effort="$REVIEWER_EFFORT"} \
    -s "$REVIEWER_SANDBOX" \
    - < "$1"
}

# ── Worktree lifecycle hooks (project-defined) ───────────────────────────────
# create-worktree.sh calls setup AFTER forking the branch + symlinking; it receives the
# absolute app dir inside the new worktree. Do per-worktree install + client generation
# here. Default: no-op.
#
# Example for a pnpm + Prisma project:
#   pipeline_worktree_setup() {
#     local app="$1"
#     ( cd "$app" && CI=true pnpm install --frozen-lockfile ) || return 1
#     ( cd "$app" && ./node_modules/.bin/prisma generate )
#   }
pipeline_worktree_setup() { :; }

# cleanup-worktree.sh calls teardown BEFORE removing the worktree (same arg). Use it to
# repair anything a per-worktree install may have repointed in the main checkout.
pipeline_worktree_teardown() { :; }

# ── Symlinks into a new worktree ─────────────────────────────────────────────
# Gitignored paths that are SAFE to share from the main checkout (e.g. ".env storage").
# Space-separated, relative to the app dir. NEVER list node_modules or a generated client —
# a shared stale client silently breaks tests; the setup hook builds fresh ones.
PIPELINE_WORKTREE_SYMLINKS=""
